package test;

import org.eclipse.jface.viewers.ArrayContentProvider; // Import should not trigger
import org.eclipse.jface.viewers.IContentProvider;
import org.eclipse.jface.viewers.TableViewer;
import org.eclipse.jface.viewers.Viewer;
import org.eclipse.swt.SWT;
import org.eclipse.swt.widgets.Composite;

public class MyClass2 {
    void setup(Composite composite) {
        TableViewer viewer = new TableViewer(composite, SWT.SINGLE | SWT.BORDER);
        viewer.setContentProvider(new OtherContentProvider()); // Should not match
        viewer.setInput(new Object[]{"item1", "item2"});
    }
}

class OtherContentProvider implements IContentProvider {
    @Override
    public void dispose() {}
    @Override
    public void inputChanged(Viewer viewer, Object oldInput, Object newInput) {}
}
